import{_ as o,o as a,c,a2 as d}from"./chunks/framework.ClgMjOt7.js";const h=JSON.parse('{"title":"プライバシー & セキュリティ保護仕様","description":"アプリロック、生体認証、電卓偽装モード、タスク隠蔽、スクリーンショット保護","frontmatter":{"title":"プライバシー & セキュリティ保護仕様","description":"アプリロック、生体認証、電卓偽装モード、タスク隠蔽、スクリーンショット保護"},"headers":[],"relativePath":"features/privacy-security.md","filePath":"features/privacy-security.md","lastUpdated":1786168778000}'),r={name:"features/privacy-security.md"};function i(l,e,t,n,s,u){return a(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="プライバシー-セキュリティ保護仕様" tabindex="-1">プライバシー &amp; セキュリティ保護仕様 <a class="header-anchor" href="#プライバシー-セキュリティ保護仕様" aria-label="Permalink to &quot;プライバシー &amp; セキュリティ保護仕様&quot;">​</a></h1><p>個人データの保護、アプリの偽装表示、およびキャプション・スクリーンショット防止に関する詳細仕様です。</p><hr><h2 id="アプリロック-生体認証-applockscreen" tabindex="-1">アプリロック &amp; 生体認証 (<code>AppLockScreen</code>) <a class="header-anchor" href="#アプリロック-生体認証-applockscreen" aria-label="Permalink to &quot;アプリロック &amp; 生体認証 (`AppLockScreen`)&quot;">​</a></h2><ul><li><code>appLockEnabled</code> (<code>Boolean</code>): 4〜8 桁の PIN 暗証番号による起動保護。</li><li><code>biometricEnabled</code> (<code>Boolean</code>): Android 生体認証 (<code>BiometricPrompt</code>) による指紋/顔解錠。</li><li><code>privacyModeAutoLockTiming</code>: アプリをバックグラウンドへ移行させてからロックがかかるまでの判定タイマー。 <ul><li><code>immediate</code>: 即時ロック</li><li><code>30s</code> / <code>1m</code> / <code>5m</code> / <code>10m</code>: 指定時間経過後にロック</li><li><code>disabled</code>: 自動ロック無効</li></ul></li></ul><hr><h2 id="電卓偽装モード-calculatorscreen-calculatorengine" tabindex="-1">電卓偽装モード (<code>CalculatorScreen</code> / <code>CalculatorEngine</code>) <a class="header-anchor" href="#電卓偽装モード-calculatorscreen-calculatorengine" aria-label="Permalink to &quot;電卓偽装モード (`CalculatorScreen` / `CalculatorEngine`)&quot;">​</a></h2><p>ロック画面を一般的な電卓 UI へ偽装するセキュリティ機能です。</p><h3 id="_1-演算評価エンジン-calculatorengine" tabindex="-1">1. 演算評価エンジン (<code>CalculatorEngine</code>) <a class="header-anchor" href="#_1-演算評価エンジン-calculatorengine" aria-label="Permalink to &quot;1. 演算評価エンジン (`CalculatorEngine`)&quot;">​</a></h3><p>実在する電卓として四則演算（加減乗除、小数点、単項マイナス）を正しく計算・評価します。</p><ul><li><strong>字句解析 (<code>tokenize</code>)</strong>: 入力文字列から数値トークンおよび演算子 (<code>+</code>, <code>-</code>, <code>*</code>, <code>/</code>) を抽出。</li><li><strong>再帰降下パーサー (Recursive Descent Parser)</strong>: <ul><li><code>parseAddSub</code>: 加算・減算の評価</li><li><code>parseMulDiv</code>: 乗算・除算の評価（ゼロ除算時は <code>NaN</code> 返却）</li><li><code>parseUnary</code>: 単項符号の評価</li><li><code>parsePrimary</code>: 数値リテラルの評価</li></ul></li></ul><h3 id="_2-ステルス解錠メカニズム" tabindex="-1">2. ステルス解錠メカニズム <a class="header-anchor" href="#_2-ステルス解錠メカニズム" aria-label="Permalink to &quot;2. ステルス解錠メカニズム&quot;">​</a></h3><ul><li><strong>通常解錠</strong>: 設定した PIN コードを数値として入力し、<code>=</code> ボタンを押すことでアンロック。</li><li><strong>パターンC (右上隅タップ解錠)</strong>: 電卓画面の右上領域を指定時間内に連続タップすることで、非常用解錠コード入力ダイアログ (<code>OverlayDialog</code>) が起動。</li></ul><h3 id="_3-動的アイコン・アプリアンサンブル変更" tabindex="-1">3. 動的アイコン・アプリアンサンブル変更 <a class="header-anchor" href="#_3-動的アイコン・アプリアンサンブル変更" aria-label="Permalink to &quot;3. 動的アイコン・アプリアンサンブル変更&quot;">​</a></h3><ul><li><code>dummyAppName</code>: ホーム画面上のアプリタイトルを「電卓」へ変更。</li><li><code>dummyIconVariant</code>: アプリアイコンを電卓風のアイコン (<code>ic_launcher_dummy</code>) へコンポーネント有効化 (<code>PackageManager.setComponentEnabledSetting</code>) により動的切り替え。</li></ul><hr><h2 id="画面・画面キャプション保護-privacymodesettingsscreen" tabindex="-1">画面・画面キャプション保護 (<code>PrivacyModeSettingsScreen</code>) <a class="header-anchor" href="#画面・画面キャプション保護-privacymodesettingsscreen" aria-label="Permalink to &quot;画面・画面キャプション保護 (`PrivacyModeSettingsScreen`)&quot;">​</a></h2><ul><li><code>secureWindow</code> (<code>FLAG_SECURE</code>): 有効時、Android の Window フラグ <code>WindowManager.LayoutParams.FLAG_SECURE</code> をセットし、画面のスクリーンショット撮影、画面録画、および外部ディスプレイへのキャストを遮断。</li><li><code>hideRecents</code>: 有効時、Android のタスクスイッチャー（最近使ったアプリ）画面でのプレビュー表示をぼかし・マスキング保護。</li></ul>',18)])])}const m=o(r,[["render",i]]);export{h as __pageData,m as default};
